import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Διαχείριση ενημερώσεων λογισμικού","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/software-update-manager.md","filePath":"el/plus/software-update-manager.md"}'),s={name:"el/plus/software-update-manager.md"};function i(l,a,n,d,p,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="διαχειριση-ενημερωσεων-λογισμικου" tabindex="-1">Διαχείριση ενημερώσεων λογισμικού <a class="header-anchor" href="#διαχειριση-ενημερωσεων-λογισμικου" aria-label="Permalink to &quot;Διαχείριση ενημερώσεων λογισμικού&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="ελεγχος-εκδοσης" tabindex="-1">Έλεγχος έκδοσης <a class="header-anchor" href="#ελεγχος-εκδοσης" aria-label="Permalink to &quot;Έλεγχος έκδοσης&quot;">​</a></h2><ol><li>Στο Company Settings ανοίξτε Software Updates / System Updates, εφόσον επιτρέπεται. Επιλέξτε Check for updates και ελέγξτε εγκατεστημένη και υποψήφια έκδοση.</li><li>Δείτε <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a> και <a href="/el/changelog/">Ιστορικό αλλαγών</a>. Νεότερη έκδοση δεν αποδεικνύει ετοιμότητα. Ελέγξτε Advanced diagnostics αν υπάρχει αβεβαιότητα διαθεσιμότητας ή συμβατότητας σχήματος.</li><li>Πριν από εξουσιοδοτημένη ανάπτυξη επιβεβαιώστε υπογραφή, ταυτότητα έκδοσης, ετοιμότητα migrations, αναγνωσιμότητα αντιγράφου, σχέδιο επαναφοράς και διατήρηση εταιρικών δεδομένων, domains, διαπιστευτηρίων, παρόχων και τοπικών προτύπων.</li><li>Ο προστατευμένος updater staging εμφανίζει Update Now μόνο όταν επιτρέπουν οι έλεγχοι. Demo και μη εγκεκριμένες εγκαταστάσεις δεν εκκινούν προστατευμένη έκδοση. Ο οδηγός δεν επιβεβαιώνει εμπορική εγκατάσταση πελάτη ή αυτόματες αναβαθμίσεις παραγωγής.</li></ol><h2 id="επιβεβαιωση-εγκαταστασης" tabindex="-1">Επιβεβαίωση εγκατάστασης <a class="header-anchor" href="#επιβεβαιωση-εγκαταστασης" aria-label="Permalink to &quot;Επιβεβαίωση εγκατάστασης&quot;">​</a></h2><p>Μετά από ρητή έγκριση, υποβάλετε ενημέρωση μόνο με υποστηριζόμενη ελεγχόμενη διαδικασία. Μην επαναλαμβάνετε όσο εκκρεμεί ή εκτελείται. Επιβεβαιώστε ότι ο διακομιστής αναφέρει επαληθευμένη νέα έκδοση και κατόπιν ανανεώστε την εφαρμογή. Σε φαινομενική καθυστέρηση δείτε διαγνωστικά και ζητήστε έλεγχο αποδεικτικού εγκατάστασης και υπηρεσίας. Αίτημα, timeout ή tag GitHub δεν αποδεικνύουν επιτυχία.</p><p>Ελέγξτε έκδοση, υπηρεσία, σχήμα, διατήρηση ρυθμίσεων και εγκεκριμένες δοκιμές. Σε αποτυχία χρησιμοποιήστε εγκεκριμένη επαναφορά· ποτέ ανεξέλεγκτη αντιστροφή migration.</p><p>Δείτε <a href="/el/installation/">Εγκατάσταση</a> και <a href="/el/security-privacy/">Ασφάλεια</a>.</p>',8)])])}const f=e(s,[["render",i]]);export{u as __pageData,f as default};
